/** static void CreateWildMon(u16 species, u8 level) */
export function CreateWildMon(species: any, level: any): any {
  let checkCuteCharm: any = null;

      ZeroEnemyPartyMons();
      checkCuteCharm = TRUE;

      switch (gSpeciesInfo[species].genderRatio)
      {
      case MON_MALE:
      case MON_FEMALE:
      case MON_GENDERLESS:
          checkCuteCharm = FALSE;
          break;
      }

      if (checkCuteCharm
          && !GetMonData(gPlayerParty[0], MON_DATA_SANITY_IS_EGG)
          && GetMonAbility(gPlayerParty[0]) == ABILITY_CUTE_CHARM
          && Random() % 3 != 0)
      {
          let leadingMonSpecies: any = GetMonData(gPlayerParty[0], MON_DATA_SPECIES);
          let leadingMonPersonality: any = GetMonData(gPlayerParty[0], MON_DATA_PERSONALITY);
          let gender: any = GetGenderFromSpeciesAndPersonality(leadingMonSpecies, leadingMonPersonality);

           
          if (gender == MON_FEMALE)
              gender = MON_MALE;
          else
              gender = MON_FEMALE;

          CreateMonWithGenderNatureLetter(gEnemyParty[0], species, level, USE_RANDOM_IVS, gender, PickWildMonNature(), 0);
          return;
      }

      CreateMonWithNature(gEnemyParty[0], species, level, USE_RANDOM_IVS, PickWildMonNature());
}

/** static bool8 TryGenerateWildMon(const struct WildPokemonInfo *wildMonInfo, u8 area, u8 flags) */
export function TryGenerateWildMon(wildMonInfo: any, area: any, flags: any): any {
  let wildMonIndex: any = 0;
      let level: any = null;

      switch (area)
      {
      case WILD_AREA_LAND:
          if (TRY_GET_ABILITY_INFLUENCED_WILD_MON_INDEX(wildMonInfo.wildPokemon, TYPE_STEEL, ABILITY_MAGNET_PULL,wildMonIndex, LAND_WILD_COUNT))
              break;
          if (TRY_GET_ABILITY_INFLUENCED_WILD_MON_INDEX(wildMonInfo.wildPokemon, TYPE_ELECTRIC, ABILITY_STATIC,wildMonIndex, LAND_WILD_COUNT))
              break;

          wildMonIndex = ChooseWildMonIndex_Land();
          break;
      case WILD_AREA_WATER:
          if (TRY_GET_ABILITY_INFLUENCED_WILD_MON_INDEX(wildMonInfo.wildPokemon, TYPE_ELECTRIC, ABILITY_STATIC,wildMonIndex, WATER_WILD_COUNT))
              break;

          wildMonIndex = ChooseWildMonIndex_WaterRock();
          break;
      case WILD_AREA_ROCKS:
          wildMonIndex = ChooseWildMonIndex_WaterRock();
          break;
      }

      level = ChooseWildMonLevel(wildMonInfo.wildPokemon[wildMonIndex]);
      if (flags & WILD_CHECK_REPEL && !IsWildLevelAllowedByRepel(level))
          return FALSE;
      if (gMapHeader.mapLayoutId != LAYOUT_BATTLE_FRONTIER_BATTLE_PIKE_ROOM_WILD_MONS && flags & WILD_CHECK_KEEN_EYE && !IsAbilityAllowingEncounter(level))
          return FALSE;

      CreateWildMon(wildMonInfo.wildPokemon[wildMonIndex].species, level);
      return TRUE;
}

/** static u16 GenerateFishingWildMon(const struct WildPokemonInfo *wildMonInfo, u8 rod) */
export function GenerateFishingWildMon(wildMonInfo: any, rod: any): any {
  let wildMonIndex: any = ChooseWildMonIndex_Fishing(rod);
      let level: any = ChooseWildMonLevel(wildMonInfo.wildPokemon[wildMonIndex]);

      CreateWildMon(wildMonInfo.wildPokemon[wildMonIndex].species, level);
      return wildMonInfo.wildPokemon[wildMonIndex].species;
}

